/**
 * What this build's audio engine can do, so the UI hides what it can't (stream ios-eq: MPVKit's
 * FFmpeg has no Rubber Band and no reverb filters; speed runs on `scaletempo2`).
 */
public struct AudioCapabilities {
    public var pitch: Bool
    public var reverb: Bool
    public var speed: Bool
    /**
     * `full` (desktop FFmpeg: shelves + limiter) or `portable` (equalizer + volume only).
     */
    public var eqFlavor: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(pitch: Bool, reverb: Bool, speed: Bool, 
        /**
         * `full` (desktop FFmpeg: shelves + limiter) or `portable` (equalizer + volume only).
         */eqFlavor: String) {
        self.pitch = pitch
        self.reverb = reverb
        self.speed = speed
        self.eqFlavor = eqFlavor
    }
}

