    public static func ==(lhs: AudioCapabilities, rhs: AudioCapabilities) -> Bool {
        if lhs.pitch != rhs.pitch {
            return false
        }
        if lhs.reverb != rhs.reverb {
            return false
        }
        if lhs.speed != rhs.speed {
            return false
        }
        if lhs.eqFlavor != rhs.eqFlavor {
            return false
        }
        return true
